from pathlib import Path
p=Path('.tmp-test-artifact-custody.py')
s=p.read_text()
old="""patch('verify-prompt-semantics.mjs',\n'''if(!testFields.EXECUTION_MODE||!testFields.REQUIRED_CAPABILITY||!testFields.ARTIFACT_REQUIREMENTS)throw new Error('TEST execution responsibility is not explicit in the canonical schema.');''',\n'''if(!testFields.EXECUTION_MODE||!testFields.REQUIRED_CAPABILITY||!testFields.ARTIFACT_REQUIREMENTS)throw new Error('TEST execution responsibility is not explicit in the canonical schema.');if(testFields.TEST_ARTIFACT_IDS?.producer!==schema.PRODUCER.APPLICATION||testFields.TEST_ARTIFACT_IDS?.valueType!=='REFERENCE_ARRAY')throw new Error('TEST artifact custody is not application-owned canonical identity.');''')\npatch('verify-prompt-semantics.mjs',\n'''if(!appSource.includes('Verification execution')||!appSource.includes('Who performs the current tests'))throw new Error('Operator UI does not explain test execution responsibility.');''',\n'''if(!appSource.includes('Verification execution')||!appSource.includes('Who performs the current tests'))throw new Error('Operator UI does not explain test execution responsibility.');if(!appSource.includes('returned artifact bytes')||!appSource.includes('filename or claimed hash cannot satisfy this gate'))throw new Error('Operator UI does not explain required test-artifact custody.');''')"""
new="""patch('verify-prompt-semantics.mjs',\n''' for(const field of ['EXECUTION_MODE','REQUIRED_CAPABILITY','ARTIFACT_REQUIREMENTS'])if(!test.fields.includes(field)||!test.required.includes(field)||test.fieldDefinitions[field]?.producer!==schema.PRODUCER.AGENT)throw new Error(`TEST execution contract is missing agent field ${field}.`);''',\n''' for(const field of ['EXECUTION_MODE','REQUIRED_CAPABILITY','ARTIFACT_REQUIREMENTS'])if(!test.fields.includes(field)||!test.required.includes(field)||test.fieldDefinitions[field]?.producer!==schema.PRODUCER.AGENT)throw new Error(`TEST execution contract is missing agent field ${field}.`);\n if(!test.fields.includes('TEST_ARTIFACT_IDS')||test.fieldDefinitions.TEST_ARTIFACT_IDS?.producer!==schema.PRODUCER.APPLICATION||test.fieldDefinitions.TEST_ARTIFACT_IDS?.valueType!=='REFERENCE_ARRAY')throw new Error('TEST artifact custody is not application-owned canonical identity.');''')\npatch('verify-prompt-semantics.mjs',\n''' if(!ui.includes('Verification execution')||!ui.includes('a filename, hash claim, or code block is not file possession')||!ui.includes('Who performs the current tests'))throw new Error('Operator UI does not explain test execution responsibility and returned-file transfer.');''',\n''' if(!ui.includes('Verification execution')||!ui.includes('a filename, hash claim, or code block is not file possession')||!ui.includes('Who performs the current tests'))throw new Error('Operator UI does not explain test execution responsibility and returned-file transfer.');\n if(!ui.includes('returned artifact bytes')||!ui.includes('filename or claimed hash cannot satisfy this gate'))throw new Error('Operator UI does not explain required test-artifact custody.');''')"""
if s.count(old)!=1: raise SystemExit(f'expected semantic locator block once, found {s.count(old)}')
p.write_text(s.replace(old,new,1))
